   326	  private Reservation reserve(String requestId, int outputCeiling) {
   327	    return service.translationTransaction(
   328	        controller,
   329	        sessionId,
   330	        1,
   331	        current -> {
   332	          var state = store.state(sessionId);
   333	          var empty = JSON.createArrayNode();
   334	          var request =
   335	              prompts.assemble(
   336	                  requestId,
   337	                  1,
   338	                  GuidedModelRequest.Kind.SOURCE_PLAN,
   339	                  current.document(),
   340	                  current.progress(),
   341	                  state,
   342	                  empty,
   343	                  empty,
   344	                  empty,
   345	                  List.of(),
   346	                  outputCeiling);
   347	          var payload =
   348	              C.object()
   349	                  .put("kind", request.kind().name())
   350	                  .put("requestId", request.requestId())
   351	                  .put("attempt", request.attempt());
   352	          payload.set("context", request.projection().document());
   353	          var complete =
   354	              C.object()
   355	                  .put("contents", payload.toString())
   356	                  .put("systemInstruction", request.outputContract());
   357	          complete.set("responseJsonSchema", request.responseSchema());
   358	          int bytes = complete.toString().getBytes(StandardCharsets.UTF_8).length + 2048;
   359	          assertThat(bytes).isLessThanOrEqualTo(translationProperties.maxInputBytes());
   360	          // Keep input headroom so refusal is genuinely output4096 rather than cumulative input.
   361	          assertThat(current.document().path("counters").path("modelInputTokens").asLong() + bytes)
   362	              .isLessThanOrEqualTo(
   363	                  current.document().path("limits").path("maxModelInputTokensTotal").asLong());
   364	          boolean existing = store.hasAttempt(sessionId, requestId, request.attempt());
   365	          if (!existing
   366	              && !service.modelReservationFitsLocked(current, bytes, request.maxOutputTokens())) {
   367	            return null;
   368	          }
   369	          String projectionHash =
   370	              GuidedContracts.hash(
   371	                  C.object()
   372	                      .setAll(
   373	                          Map.of(
   374	                              "context",
   375	                              request.projection().document(),
   376	                              "schemaPins",
   377	                              prompts.schemaProvenance())));
   378	          Instant deadline = clock.instant().plusSeconds(translationProperties.callSeconds());
   379	          var attempt =
   380	              store.reserveAttempt(
   381	                  current.document(),
   382	                  requestId,
   383	                  request.attempt(),
   384	                  request.kind().name(),
   385	                  projectionHash,
   386	                  state.path("planRevision").asLong(),
   387	                  bytes,
   388	                  request.maxOutputTokens(),
   389	                  "budget-translator",
   390	                  deadline);
   391	          if (attempt.send()) {
   392	            service.reserveModel(
   393	                controller,
   394	                sessionId,
   395	                1,
   396	                attempt.reservationKey(),
   397	                bytes,
   398	                request.maxOutputTokens());
   399	          }
   400	          return new Reservation(request, attempt, bytes, deadline);
   401	        });
   402	  }
