   404	  private void sendAndSettle(Reservation reserved, boolean unknownUsage) {
   405	    if (!reserved.attempt().send()) {
   406	      return;
   407	    }
   408	    assertThat(
   409	            service.translationTransaction(
   410	                controller,
   411	                sessionId,
   412	                1,
   413	                current ->
   414	                    store.claimSend(
   415	                        sessionId,
   416	                        reserved.attempt().attemptId(),
   417	                        "budget-translator",
   418	                        clock.instant())))
   419	        .isTrue();
   420	    GuidedLlmGatewayClient counted =
   421	        (request, budget) -> {
   422	          budget.remaining();
   423	          assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();
   424	          var committed = snapshot();
   425	          var reservation =
   426	              committed
   427	                  .path("progress")
   428	                  .path("modelReservations")
   429	                  .path(reserved.attempt().reservationKey());
   430	          assertThat(reservation.path("input").asInt()).isEqualTo(reserved.inputBytes());
   431	          assertThat(reservation.path("output").asInt()).isEqualTo(request.maxOutputTokens());
   432	          assertThat(request.maxOutputTokens()).isEqualTo(4096);
   433	          boolean committedBeforeSend =
   434	              !TransactionSynchronizationManager.isActualTransactionActive()
   435	                  && reservation.path("input").asInt() == reserved.inputBytes()
   436	                  && reservation.path("output").asInt() == request.maxOutputTokens()
   437	                  && "CALLING"
   438	                      .equals(
   439	                          jdbc.queryForObject(
   440	                              "SELECT status FROM studio_guided_model_attempts WHERE session_id=? AND attempt_id=?",
   441	                              String.class,
   442	                              sessionId,
   443	                              reserved.attempt().attemptId()));
   444	          assertThat(committedBeforeSend).isTrue();
   445	          sends++;
   446	          var witness =
   447	              C.object()
   448	                  .put("ordinal", sends)
   449	                  .put("reservedInput", reservation.path("input").asInt())
   450	                  .put("reservedOutput", reservation.path("output").asInt())
   451	                  .put("committedBeforeSend", committedBeforeSend)
   452	                  .put("completeServiceInputEnvelopeBytes", reserved.inputBytes() - 2048)
   453	                  .put(
   454	                      "cumulativeInput",
   455	                      committed.path("document").path("counters").path("modelInputTokens").asLong())
   456	                  .put(
   457	                      "cumulativeOutput",
   458	                      committed
   459	                          .path("document")
   460	                          .path("counters")
   461	                          .path("modelOutputTokens")
   462	                          .asLong());
   463	          numericWitnesses.add(witness);
   464	          if (unknownUsage) {
   465	            // This counted controlled call reports usage later, without another provider
   466	            // invocation.
   467	            pendingControlledUsage.add(
   468	                new ControlledLateUsage(reserved.attempt().attemptId(), 20, 40));
   469	          }
   470	          return new GuidedModelResponse(
   471	              unknownUsage ? GuidedModelResponse.Code.TIMEOUT : GuidedModelResponse.Code.BUSY,
   472	              null,
   473	              unknownUsage ? null : 20,
   474	              unknownUsage ? null : 40,
   475	              null);
   476	        };
   477	    var response =
   478	        counted.propose(reserved.request(), new GuidedCallBudget(reserved.deadline(), clock));
   479	    service.translationTransaction(
   480	        controller,
   481	        sessionId,
   482	        1,
   483	        current -> {
   484	          service.settleModel(
   485	              controller,
   486	              sessionId,
   487	              1,
   488	              reserved.attempt().settlementKey(),
   489	              reserved.attempt().reservationKey(),
   490	              response.inputTokens(),
   491	              response.outputTokens());
   492	          store.finishAttempt(
   493	              sessionId,
   494	              reserved.attempt().attemptId(),
   495	              unknownUsage ? "UNKNOWN_CALL" : "REJECTED",
   496	              null,
   497	              response.inputTokens(),
   498	              response.outputTokens());
   499	          return null;
   500	        });
   501	  }
