   514	        .isTrue();
   515	    assertThat(identity.path("outputCeiling").asInt()).isEqualTo(4096);
   516	    assertThat(identity.path("inputCeiling").asInt()).isEqualTo(reserved.inputBytes());
   517	    var digest = C.object();
   518	    for (String key :
   519	        List.of(
   520	            "requestId",
   521	            "attempt",
   522	            "kind",
