   160	        alternatives.size() == 1
   161	            ? alternatives.get(0)
   162	            : contracts.object().set("anyOf", alternatives);
   163	    var counts = new java.util.LinkedHashMap<String, Integer>();
   164	    var shapes = new java.util.LinkedHashMap<String, JsonNode>();
   165	    countSchemas(expanded, counts, shapes);
   166	    var names = new java.util.LinkedHashMap<String, String>();
   167	    counts.forEach(
   168	        (shape, count) -> {
   169	          if (count > 1) {
   170	            names.put(shape, "Shape" + names.size());
   171	          }
   172	        });
   173	    ObjectNode compact = (ObjectNode) compactSchema(expanded, names, null);
   174	    if (!names.isEmpty()) {
   175	      ObjectNode definitions = compact.putObject("$defs");
   176	      names.forEach(
   177	          (shape, name) -> definitions.set(name, compactSchema(shapes.get(shape), names, shape)));
   178	    }
   179	    return compact;
   180	  }
   181	
   182	  private void countSchemas(
   183	      JsonNode node,
   184	      java.util.Map<String, Integer> counts,
   185	      java.util.Map<String, JsonNode> shapes) {
   186	    if (node.isObject()) {
   187	      String canonical = GuidedContracts.canonical(node);
   188	      if (node.has("type") && canonical.length() > 120) {
   189	        counts.merge(canonical, 1, Integer::sum);
   190	        shapes.putIfAbsent(canonical, node);
   191	      }
   192	      node.elements().forEachRemaining(child -> countSchemas(child, counts, shapes));
   193	    } else {
   194	      if (node.isArray()) {
   195	        node.forEach(child -> countSchemas(child, counts, shapes));
   196	      }
   197	    }
   198	  }
   199	
   200	  private JsonNode compactSchema(
   201	      JsonNode node, java.util.Map<String, String> names, String defining) {
   202	    if (node.isArray()) {
   203	      var result = contracts.object().putArray("items");
   204	      node.forEach(child -> result.add(compactSchema(child, names, defining)));
   205	      return result;
   206	    }
   207	    if (!node.isObject()) {
   208	      return node.deepCopy();
   209	    }
   210	    String canonical = GuidedContracts.canonical(node);
   211	    if (names.containsKey(canonical) && !canonical.equals(defining)) {
   212	      return contracts.object().put("$ref", "#/$defs/" + names.get(canonical));
   213	    }
   214	    ObjectNode result = contracts.object();
   215	    node.fields()
   216	        .forEachRemaining(
   217	            entry -> result.set(entry.getKey(), compactSchema(entry.getValue(), names, defining)));
   218	    return result;
   219	  }
   220	
   221	  public ObjectNode schemaProvenance() {
   222	    ObjectNode pins =
   223	        contracts
   224	            .object()
   225	            .put("strictSchemaHash", GuidedContracts.hash(schema))
   226	            .put(
   227	                "sourceSelectionSchemaHash",
   228	                GuidedContracts.hash(
   229	                    contracts.parse(
   230	                        resource("/studio/observed-contracts/v3/source-selection.schema.json"))))
   231	            .put(
   232	                "planningContextHash",
   233	                GuidedContracts.hash(
   234	                    contracts.parse(
   235	                        resource("/studio/observed-contracts/v3/planning-context.schema.json"))))
   236	            .put(
   237	                "outputContractHash",
   238	                GuidedContracts.hash(contracts.object().put("contract", output)));
   239	    ObjectNode provider = pins.putObject("providerSchemaHashes");
   240	    for (GuidedModelRequest.Kind kind : GuidedModelRequest.Kind.values()) {
   241	      provider.put(kind.name(), GuidedContracts.hash(providerSchema(kind)));
   242	    }
   243	    return pins;
   244	  }
   245	
   246	  private JsonNode providerNode(JsonNode node) {
   247	    if (node.isArray()) {
   248	      var result = contracts.object().putArray("items");
   249	      node.forEach(child -> result.add(providerNode(child)));
   250	      return result;
   251	    }
   252	    if (!node.isObject()) {
   253	      return node.deepCopy();
   254	    }
   255	    if (node.has("$ref")) {
   256	      String reference = node.path("$ref").asText();
   257	      String prefix = "https://checks.citi.example/contracts/observed/v3/";
   258	      if (!reference.startsWith(prefix)) {
   259	        throw new IllegalStateException("Unsupported pinned guided schema reference");
   260	      }
   261	      String[] local = reference.substring(prefix.length()).split("#", -1);
   262	      if (local.length > 2
   263	          || !local[0].matches("[a-z0-9-]+\\.schema\\.json")
   264	          || local.length == 2 && !local[1].matches("/definitions/[A-Za-z0-9]+")) {
   265	        throw new IllegalStateException("Unsupported pinned guided schema reference");
   266	      }
   267	      JsonNode referenced = contracts.parse(resource("/studio/observed-contracts/v3/" + local[0]));
   268	      if (local.length == 2) {
   269	        referenced = referenced.at(local[1]);
   270	      }
   271	      if (!referenced.isObject()) {
   272	        throw new IllegalStateException("Missing pinned guided schema");
   273	      }
   274	      return providerNode(referenced);
   275	    }
   276	    ObjectNode result = contracts.object();
   277	    node.fields()
   278	        .forEachRemaining(
   279	            entry -> {
   280	              String key = entry.getKey();
   281	              if (List.of(
   282	                      "$schema",
   283	                      "$id",
   284	                      "title",
   285	                      "description",
   286	                      "allOf",
   287	                      "if",
   288	                      "then",
   289	                      "else",
   290	                      "not",
   291	                      "pattern",
   292	                      "uniqueItems",
   293	                      "minLength",
   294	                      "maxLength")
   295	                  .contains(key)) {
   296	                return;
   297	              }
   298	              if (key.equals("const")) {
   299	                JsonNode value = entry.getValue();
   300	                if (value.isTextual()) {
   301	                  result.put("type", "string").putArray("enum").add(value);
   302	                } else {
   303	                  if (value.isIntegralNumber()) {
   304	                    result.put("type", "integer").set("minimum", value);
   305	                    result.set("maximum", value);
   306	                  } else {
   307	                    if (value.isBoolean()) {
   308	                      result.put("type", "boolean");
   309	                    } else {
   310	                      if (value.isNull()) {
   311	                        result.put("type", "null");
   312	                      }
   313	                    }
   314	                  }
   315	                }
   316	
   317	              } else {
   318	                if (key.equals("properties")) {
   319	                  ObjectNode properties = result.putObject("properties");
   320	                  entry
   321	                      .getValue()
   322	                      .fields()
   323	                      .forEachRemaining(
   324	                          property ->
   325	                              properties.set(property.getKey(), providerNode(property.getValue())));
   326	                } else {
   327	                  result.set(key.equals("oneOf") ? "anyOf" : key, providerNode(entry.getValue()));
   328	                }
   329	              }
   330	            });
   331	    return result;
   332	  }
   333	
   334	  private static String resource(String name) {
   335	    try (var in = GuidedPromptAssembler.class.getResourceAsStream(name)) {
   336	      if (in == null) {
   337	        throw new IllegalStateException("Missing guided contract resource");
   338	      }
   339	      return new String(in.readAllBytes(), StandardCharsets.UTF_8);
   340	    } catch (IOException error) {
   341	      throw new IllegalStateException("Cannot read guided contract resource");
   342	    }
   343	  }
   344	}

